PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('customer','cashier','admin')), active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS auth_sessions(token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tiers(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, price_centavos INTEGER NOT NULL CHECK(price_centavos>0));
CREATE TABLE IF NOT EXISTS pcs(id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, tier_id INTEGER NOT NULL REFERENCES tiers(id), specs TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS maintenance(id INTEGER PRIMARY KEY, pc_id INTEGER NOT NULL REFERENCES pcs(id), start_at INTEGER NOT NULL, end_at INTEGER NOT NULL, reason TEXT NOT NULL, CHECK(end_at>start_at));
CREATE TABLE IF NOT EXISTS bookings(id INTEGER PRIMARY KEY, reference TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL REFERENCES users(id), pc_id INTEGER NOT NULL REFERENCES pcs(id), start_at INTEGER NOT NULL, end_at INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('held','confirmed','completed','cancelled','expired','no_show')), hold_until INTEGER NOT NULL, checkout_key TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS booking_items(id INTEGER PRIMARY KEY, booking_id INTEGER NOT NULL REFERENCES bookings(id), kind TEXT NOT NULL CHECK(kind IN ('base','extension')), slots INTEGER NOT NULL CHECK(slots BETWEEN 1 AND 16), unit_centavos INTEGER NOT NULL CHECK(unit_centavos>0), amount_centavos INTEGER NOT NULL CHECK(amount_centavos>0), status TEXT NOT NULL CHECK(status IN ('held','paid','expired','cancelled')), hold_until INTEGER NOT NULL, expected_end INTEGER NOT NULL, proposed_end INTEGER NOT NULL, extension_key TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS booking_slots(pc_id INTEGER NOT NULL REFERENCES pcs(id), start_at INTEGER NOT NULL, item_id INTEGER NOT NULL REFERENCES booking_items(id), PRIMARY KEY(pc_id,start_at));
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY, booking_id INTEGER NOT NULL REFERENCES bookings(id), item_id INTEGER NOT NULL UNIQUE REFERENCES booking_items(id), amount_centavos INTEGER NOT NULL, method TEXT NOT NULL CHECK(method IN ('cash','external')), reference TEXT NOT NULL, cashier_id INTEGER NOT NULL REFERENCES users(id), payment_key TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS receipts(id INTEGER PRIMARY KEY, number TEXT NOT NULL UNIQUE, payment_id INTEGER NOT NULL UNIQUE REFERENCES payments(id), booking_id INTEGER NOT NULL REFERENCES bookings(id), description TEXT NOT NULL, amount_centavos INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS plays(id INTEGER PRIMARY KEY, booking_id INTEGER NOT NULL UNIQUE REFERENCES bookings(id), started_at INTEGER NOT NULL, ended_at INTEGER);
CREATE TABLE IF NOT EXISTS refunds(id INTEGER PRIMARY KEY, payment_id INTEGER NOT NULL REFERENCES payments(id), booking_id INTEGER NOT NULL REFERENCES bookings(id), amount_centavos INTEGER NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected','completed')), requested_by INTEGER NOT NULL REFERENCES users(id), approved_by INTEGER NOT NULL DEFAULT 0, completed_by INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, completed_at INTEGER);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, actor_id INTEGER NOT NULL, action TEXT NOT NULL, entity_id INTEGER NOT NULL, created_at INTEGER NOT NULL);
